-- 095: Ankara source-backed cleanup and foreign-label cleanup in Kırklareli.
-- Preserve meaningful attractions; deactivate only obvious duplicate records and clearly misplaced foreign labels.
UPDATE public.places SET short_description='Türkiye Cumhuriyeti’nin kurucusu Mustafa Kemal Atatürk’ün anıt mezarı ve Cumhuriyet tarihini anlatan müze kompleksi.', long_description='Anıtkabir, Anıttepe’de yer alan anıt mezar ve Atatürk ile Kurtuluş Savaşı Müzesi’nden oluşur. Ankara’nın en önemli tarihî ve kamusal ziyaret noktalarındandır.', source_url='https://ankara.ktb.gov.tr/TR-395997/anitkabir.html', verified=true, trust_score=98, content_review_status='source_backed', updated_at=now() WHERE city='Ankara' AND slug='anitkabir';
UPDATE public.places SET short_description='Roma, Bizans, Selçuklu ve Osmanlı dönemlerinin izlerini taşıyan, tarihî Ankara’nın merkezindeki kale.', long_description='Ankara Kalesi, kentin en eski yerleşim alanlarından birinde bulunur. Kale çevresindeki geleneksel Ankara evleri, dar sokaklar ve kültür duraklarıyla birlikte gezilebilir.', source_url='https://ankara.ktb.gov.tr/TR-391154/tarih--kultur-turizmi.html', verified=true, trust_score=96, content_review_status='source_backed', updated_at=now() WHERE city='Ankara' AND slug='ankara-kalesi';
UPDATE public.places SET short_description='Paleolitik dönemden farklı uygarlıklara uzanan Anadolu arkeolojik eserlerini kronolojik olarak sergileyen müze.', long_description='Anadolu Medeniyetleri Müzesi, Ankara Kalesi’nin güneydoğusunda yer alan Mahmut Paşa Bedesteni ve Kurşunlu Han yapılarında hizmet verir; Anadolu’nun arkeolojik mirasını dönemler boyunca tanıtır.', source_url='https://ankara.ktb.gov.tr/TR-259775/anadolu-medeniyetleri-muzesi.html', verified=true, trust_score=98, content_review_status='source_backed', updated_at=now() WHERE city='Ankara' AND slug='anadolu-medeniyetleri-muzesi';
UPDATE public.places SET short_description='Ankara Ulus’ta Roma dönemine tarihlenen tiyatro kalıntıları ve arkeolojik alan.', long_description='Ankara Roma Tiyatrosu, 1980’lerde yapılan çalışmalar sırasında ortaya çıkarılan ve MS 2. yüzyıl başlarına tarihlenen antik tiyatro kalıntılarını içerir.', source_url='https://ankara.ktb.gov.tr/Eklenti/48859,ankararehberi2016pdf.pdf?0=', verified=true, trust_score=92, content_review_status='source_backed', updated_at=now() WHERE city='Ankara' AND slug='osm-node-4993196022';
UPDATE public.places SET short_description='Kavaklıdere’de kuğuları, küçük şelalesi ve yürüyüş alanıyla tanınan kent parkı.', long_description='Kuğulu Park, Tunalı Hilmi Caddesi çevresindeki kent yaşamının simgelerindendir; kuğuların bulunduğu göleti ve dinlenme alanlarıyla kısa bir şehir molası sunar.', source_url='https://s.ankara.bel.tr/files/7016/1417/1042/bil-bul-ankaraa.pdf', verified=true, trust_score=92, content_review_status='source_backed', updated_at=now() WHERE city='Ankara' AND slug='kugulu-park';
UPDATE public.places SET short_description='Ankara Garı ve Opera binaları arasında yer alan; göleti, yürüyüş alanları ve eğlence olanaklarıyla bilinen büyük kent parkı.', long_description='Gençlik Parkı, Ankara merkezinde dinlenme ve açık hava etkinlikleri için kullanılan önemli kamusal yeşil alanlardan biridir.', source_url='https://s.ankara.bel.tr/files/7016/1417/1042/bil-bul-ankaraa.pdf', verified=true, trust_score=92, content_review_status='source_backed', updated_at=now() WHERE city='Ankara' AND slug='genclik-parki';
UPDATE public.places SET short_description='Ankara’nın panoramik kent manzarasıyla bilinen seyir noktası ve açık hava alanı.', long_description='50. Yıl Parkı, Ankara manzarasını izlemek ve açık havada vakit geçirmek için kullanılan yüksek konumlu kent parkıdır.', source_url='https://ankara.ktb.gov.tr/TR-152350/gezilecek-yerler.html', verified=true, trust_score=88, content_review_status='source_backed', updated_at=now() WHERE city='Ankara' AND slug='50-yil-parki';
UPDATE public.places SET is_active=false, content_review_status='rejected', updated_at=now() WHERE city='Ankara' AND slug IN ('osm-node-34668145','osm-node-3058034430') AND EXISTS (SELECT 1 FROM public.places p WHERE p.city='Ankara' AND p.slug IN ('anitkabir','ankara-kalesi') AND p.is_active=true AND p.content_review_status='source_backed' AND lower(trim(p.name))=lower(trim(public.places.name));
UPDATE public.places SET is_active=false, content_review_status='rejected', updated_at=now() WHERE city='Kırklareli' AND slug IN ('osm-node-5013440917','osm-node-3997204203') AND (latitude > 41.95 AND longitude < 27.55);
